import random
def alarm():                                   # 확률 프로그램: 부모 먼저
    B = int(random.random() < 0.05)
    E = int(random.random() < 0.05)
    return {"B": B, "E": E, "A": B | E}
def rejection(program, query, evidence, n):
    counts, kept = {0: 0, 1: 0}, 0
    for _ in range(n):
        s = program()
        if evidence(s):
            counts[query(s)] += 1; kept += 1
    return {k: v / kept for k, v in counts.items()} if kept else None, kept
random.seed(0)
for n in (300, 10_000, 1_000_000):
    est, kept = rejection(alarm, lambda s: s["B"], lambda s: s["A"] == 1, n)
    print(n, "kept", kept, "P(B=1|A=1)~", round(est[1], 4))

p_a = {0: 0.5, 1: 0.5}
f = lambda parent, child: 0.8 if parent == child else 0.2   # p(b|a), p(c|b)
def joint_prob(x):                       # 모든 인자를 곱한다
    return p_a[x["A"]] * f(x["A"], x["B"]) * f(x["B"], x["C"])
def blanket_prob(x, var):                # var 를 건드리는 인자만 곱한다
    if var == "A": return p_a[x["A"]] * f(x["A"], x["B"])
    if var == "B": return f(x["A"], x["B"]) * f(x["B"], x["C"])
def cond(x, var, score):
    w = {v: score({**x, var: v}) for v in (0, 1)}
    z = sum(w.values())
    return {v: round(w[v] / z, 4) for v in w}
x = {"A": 1, "B": 0, "C": 1}
for var in ("A", "B"):
    print(var, cond(x, var, lambda y: joint_prob(y)),
               cond(x, var, lambda y: blanket_prob(y, var)))

import numpy as np
def score(b, e, a=1):                      # p(b) p(e) p(a | b, e), A = B or E
    return (0.05 if b else 0.95) * (0.05 if e else 0.95) * (1.0 if a == (b | e) else 0.0)
def gibbs_alarm(iters, rng):
    b, e, hits, visits = 1, 1, 0, {}
    for _ in range(iters):
        w = np.array([score(0, e), score(1, e)]); b = rng.choice(2, p=w / w.sum()); hits += b
        w = np.array([score(b, 0), score(b, 1)]); e = rng.choice(2, p=w / w.sum()); hits += b
        visits[(b, e)] = visits.get((b, e), 0) + 1
    return hits / (2 * iters), visits
for seed in range(4):
    est, _ = gibbs_alarm(100, np.random.default_rng(seed))
    print("100 sweeps, seed", seed, "->", round(est, 3))
est, visits = gibbs_alarm(200_000, np.random.default_rng(0))
print("200000 sweeps ->", round(est, 4), "visits", visits)

def independent(parents, x, y, given=()):
    nodes, shaded = set(parents), set(given)
    while True:                                  # 2) 칠하지 않은 잎을 되풀이해 지운다
        kids = {p for n in nodes for p in parents[n] if p in nodes}
        leaves = {n for n in nodes if n not in kids and n not in shaded | {x, y}}
        if not leaves: break
        nodes -= leaves
    adj = {n: set() for n in nodes}
    for n in nodes:
        ps = [p for p in parents[n] if p in nodes]
        for p in ps: adj[n].add(p); adj[p].add(n)          # 방향을 지운다
        for p in ps: adj[p] |= set(ps) - {p}              # 3) 부모끼리 잇는다(결혼)
    seen, stack = {x}, [x]                       # 4) 칠한 노드를 피해 x -> y 길이 있나
    while stack:
        for m in adj[stack.pop()] - seen - shaded:
            if m == y: return False
            seen.add(m); stack.append(m)
    return True
